import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%81%9D%E3%82%8C%E3%81%A3%E3%81%BD%E3%81%8F%E6%8F%8F%E3%81%8F%E3%82%B3%E3%83%842%E5%91%A8%E7%9B%AE.html","title":"それっぽく描くコツ2周目","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":3.88,"words":1165},"filePathRelative":"それっぽく描くコツ2周目.md"}`),a={name:`それっぽく描くコツ2周目.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="それっぽく描くコツ2周目" tabindex="-1"><a class="header-anchor" href="#それっぽく描くコツ2周目"><span>それっぽく描くコツ2周目</span></a></h1><p><a href="./【書籍】イラストをそれっぽく描くコツ.html">【書籍】イラストをそれっぽく描くコツ</a>の練習、2周目。 リベンジ編とも言う。</p><p><a href="./それっぽく描くコツ1周目.html">それっぽく描くコツ1周目</a>で気に食わなかった奴を再挑戦する。再挑戦はちょっと頑張る。 同じ条件で描く訳では無いので成長だけの違いでは無いが、まぁ差分は成長って事にしておこう。</p><h2 id="リベンジ編1-描いてみよう、ロングヘア-2026-07-14" tabindex="-1"><a class="header-anchor" href="#リベンジ編1-描いてみよう、ロングヘア-2026-07-14"><span>リベンジ編1: 描いてみよう、ロングヘア（2026/07/14)</span></a></h2><p><a href="https://www.youtube.com/live/3O6GaRrGbdc" target="_blank" rel="noopener noreferrer">書籍：イラストをそれっぽく描くコツの練習ライブシーズン2、描いてみようの娘（最初）〜 - YouTube</a></p><p><img src="/RandomThoughts/assets/2026_0714_211817-DKU1y5tk.png" alt="imgs/Soreppoku/2026_0714_211817.png"></p><p>描いてみようの子。あんま変わらない気もするが、2周目の方が好きかな。 この子は１周目もそんなに嫌いでは無いが。</p><p><img src="/RandomThoughts/assets/2026_0714_211928-CrRBPB29.png" alt="imgs/Soreppoku/2026_0714_211928.png"></p><p>これは2周目でもあまりうまくいっている気はしないけれど、1周目よりは2周目の方が好きかな。 板タブとiPadの違いもあるが、線を引くのはなれてきた気はする。</p><h2 id="リベンジ編2-ポニーテールっぽく-2026-07-15" tabindex="-1"><a class="header-anchor" href="#リベンジ編2-ポニーテールっぽく-2026-07-15"><span>リベンジ編2: ポニーテールっぽく (2026/07/15)</span></a></h2><p><a href="https://www.youtube.com/live/Xz2ad8ybw4c" target="_blank" rel="noopener noreferrer">書籍：イラストをそれっぽく描くコツの練習ライブ、リベンジ編、ポニーテールっぽく描きたい〜 - YouTube</a></p><p><img src="/RandomThoughts/assets/2026_0715_203410--J4yYY0H.png" alt="imgs/Soreppoku/2026_0715_203410.png"></p><p>今回は一つで終わってしまったがまぁいいか、という事で。 割と可愛く描けたヽ(´ー｀)ノ</p><h2 id="リベンジ編3-オールバックっぽく-2026-07-16" tabindex="-1"><a class="header-anchor" href="#リベンジ編3-オールバックっぽく-2026-07-16"><span>リベンジ編3: オールバックっぽく（2026/07/16）</span></a></h2><p><a href="https://www.youtube.com/live/0nyzYJyykJU" target="_blank" rel="noopener noreferrer">書籍：イラストをそれっぽく描くコツの練習ライブ、リベンジ編、オールバックっぽく描きたい〜 - YouTube</a></p><p><img src="/RandomThoughts/assets/2026_0716_210636-X6hNyys8.png" alt="imgs/Soreppoku/2026_0716_210636.png"></p><p>少しフカン度合いが弱い気はするが、こんなもんかな、という気はする。やはりこれはなかなか難しいね。</p><h2 id="リベンジ編4-ツンツンヘア-2026-07-17" tabindex="-1"><a class="header-anchor" href="#リベンジ編4-ツンツンヘア-2026-07-17"><span>リベンジ編4: ツンツンヘア (2026/07/17)</span></a></h2><ul><li><a href="https://www.youtube.com/live/TeH-q8Ahozo" target="_blank" rel="noopener noreferrer">書籍：イラストをそれっぽく描くコツの練習ライブ、リベンジ編、ツンツンヘアっぽく描きたい〜 - YouTube</a></li><li><a href="https://www.youtube.com/live/jeZQSweAZlc" target="_blank" rel="noopener noreferrer">書籍：イラストをそれっぽく描くコツの練習ライブ、リベンジ編、ツンツンヘアっぽく描きたい2〜 - YouTube</a></li></ul><p>なぜか通信エラーで切れてしまったので作り直し。</p><p><img src="/RandomThoughts/assets/2026_0717_211233-Da7_5TLm.png" alt="imgs/Soreppoku/2026_0717_211233.png"></p><p>いやー、これは全然うまくいかずに無駄に時間が掛かってしまった！こういう無駄に時間掛かるのは無くしたいので今回は失敗だったなぁ。</p><p>ツンツンヘアはそれっぽい気もするけれど、アオリはマスター出来ていない感じがするのでもうちょっと練習したいね。</p><h2 id="リベンジ編5-アオリをひたすら描く-2026-07-18" tabindex="-1"><a class="header-anchor" href="#リベンジ編5-アオリをひたすら描く-2026-07-18"><span>リベンジ編5: アオリをひたすら描く (2026/07/18)</span></a></h2><p><a href="https://www.youtube.com/live/kvm8F02S728" target="_blank" rel="noopener noreferrer">書籍：イラストをそれっぽく描くコツの練習ライブ、リベンジ編、アオリをひたすらく - YouTube</a></p><p>昨日のツンツンヘアがなかなか上手く描けなかったので、アオリをたくさん描いてみる事に。</p><p><img src="/RandomThoughts/assets/2026_0718_203740-CQyEV2g8.png" alt="imgs/Soreppoku/2026_0718_203740.png"></p><p>3くらいから、最初にイメージした感じに描けるようになってきた。いろいろおかしい所もあるけれど、まぁこのくらいかな、という気はする。</p><h2 id="リベンジ編6-ツーブロックっぽく描きたい-2026-07-19" tabindex="-1"><a class="header-anchor" href="#リベンジ編6-ツーブロックっぽく描きたい-2026-07-19"><span>リベンジ編6: ツーブロックっぽく描きたい(2026/07/19）</span></a></h2><p><a href="https://www.youtube.com/live/u901sXnBJQI" target="_blank" rel="noopener noreferrer">書籍：イラストをそれっぽく描くコツの練習ライブ、リベンジ編、ツーブロックっぽく描きたい〜 - YouTube</a></p><p><img src="/RandomThoughts/assets/2026_0719_204426-0YwfN-u0.png" alt="imgs/Soreppoku/2026_0719_204426.png"></p><p>髪型は一周目も嫌いでは無いんだが、今ならもうちょい上手く描けるかな？と思って描いてみた。ついでに顔も描いてみた。 やっぱ顔ある方がいいよな。</p><p>髪型も立体感が改善しているかな。全体的には上達している気がする。</p><h2 id="_2周目はバランスが大きく改善している" tabindex="-1"><a class="header-anchor" href="#_2周目はバランスが大きく改善している"><span>2周目はバランスが大きく改善している</span></a></h2><p>最初の数枚はたまたまマシな事もあるかな、としばらく結論は出さずに進めていたが、ここまで描いたのを見直すと全体的なバランスが改善している。 ぱっと見の印象はだいぶ良くなっているように思う。</p><p>1周目でシルエットとアタリの段階で最終的な失敗パターンをいろいろ経験した結果、最初の段階で少し試行錯誤出来るようになった。 シルエットからアタリの一方通行だけでなくアタリからシルエットに少しフィードバックして直したりもしている。 あまり直してばかりで進まない感じにはしたくなかったが、アタリとシルエットくらいだとそこまで時間は掛からないので、このくらいならいいかな、と思っている。</p><p>この試行錯誤で全体的にどういう感じにしたいかを固めて進められるようになり、最終的な出来がこの段階の試行錯誤で調整出来るようになったと思う。 このくらいでいいか、という感じになったら進めて、まぁこのくらいだな、という完成になる。 これはたぶん一周目の最初の段階では出来なかったと思うので、このやり方で進めた成長と思う。</p><p>このシルエットとあたりの段階で全体的な事がある程度予想出来るようになった事と、あとは各線を引いている時にその全体的な事をある程度意識出来るようになったのが大きな違いに思う。自分が今描いている線がなんなのか良く分からない、みたいな事は減ったし、バランス感覚を働かせながら線を引ける事が増えた。 これはシルエットから描く描き方の副作用と思う。最初から全体的な事を気にするので、途中も全体的な事を気にしながら進めやすい。 1周目は「このシルエット意味無くね？」という感じになる事も多かったが、2周目は最初に固めたなんとなくのイメージでバランスをとっていく感じにできているので、有効活用出来ている感じがある。</p><p>線もその全体的な事の中で引くので、この線はここまでひく、みたいなのに自信が持てている。のびのび引けるようになった気がする。</p><p>ただ描く時間は1.5倍くらいになっていると思う。1周目は一度のライブで2枚描けていたのが、2周目は1枚になっている。 ただ喋ったり準備したりといろいろやっているので、2倍にはなっていない。たぶん1枚に30分は掛からないくらいかな、と思う。 もう少し手戻りを減らして20分くらいにしたいなぁ。でも30分なら休憩挟まずに完成まで行けるので、直してばかりで全然進まないという感じには感じていない。まぁ自分の絵を描くペースは今はこのくらいかな、という気がする。 練習としては1周目の方が多くを経験出来て良いかもしれないが、 出来たものの満足度は2周目だとこのくらいは欲しいので、このくらいがバランスという気がする。</p><h2 id="リベンジ編7-三つ編みっぽく-2026-07-20" tabindex="-1"><a class="header-anchor" href="#リベンジ編7-三つ編みっぽく-2026-07-20"><span>リベンジ編7: 三つ編みっぽく (2026/07/20)</span></a></h2><p><a href="https://www.youtube.com/live/WwBvfNfGJGA" target="_blank" rel="noopener noreferrer">書籍：イラストをそれっぽく描くコツの練習ライブ、リベンジ編、三つ編みっぽく描きたい〜 - YouTube</a></p><p><img src="/RandomThoughts/assets/2026_0720_201345-BmkNK6Gr.png" alt="imgs/Soreppoku/2026_0720_201345.png"></p><p>今回はあんまり一回目と変わらないなぁ、という気もしているけれど、少し三つ編みっぽさは増したかな？という気もしている。 真ん中はもっとくいっと曲げないといけないのか、とか、ほつれが左右同じ場所に出ないようにした方が良かったな、とか後から気づいた。</p><h2 id="リベンジ編8-猫背っぽく、横向きっぽく-2026-07-21" tabindex="-1"><a class="header-anchor" href="#リベンジ編8-猫背っぽく、横向きっぽく-2026-07-21"><span>リベンジ編8: 猫背っぽく、横向きっぽく（2026/07/21）</span></a></h2><p><a href="https://www.youtube.com/live/c2_6whQBZG0" target="_blank" rel="noopener noreferrer">書籍：イラストをそれっぽく描くコツの練習ライブ、リベンジ編、猫背っぽく描きたい〜 - YouTube</a></p><p>最後通信が切れてしまったが。</p><p><img src="/RandomThoughts/assets/2026_0721_220250-DxPTlpHi.png" alt="imgs/Soreppoku/2026_0721_220250.png"></p><p>アフター1は全然駄目だなぁ、という感じ。アフター2はまぁまぁか？</p><p><img src="/RandomThoughts/assets/2026_0721_220323-DLdin9Qe.png" alt="imgs/Soreppoku/2026_0721_220323.png"></p><p>こっちはビフォーもそんなに悪いとは思ってないし、アフターもそんなに変わらない気はしているが、 身体の大きさを最初に思った通りに描けているのでそこは描こうと思ったものがより描けているという満足感はある。</p><p>最後通信エラーで終わってしまったので仕上げが不十分だが、まぁだいたいは出来たので終わりでいいかな。</p><p>二つ見た感じ、まぁこんなもんかな、という気はしている。</p><h2 id="_2周目を終えての感想-かなり上手くなったんじゃないか" tabindex="-1"><a class="header-anchor" href="#_2周目を終えての感想-かなり上手くなったんじゃないか"><span>2周目を終えての感想: かなり上手くなったんじゃないか？</span></a></h2><p>2周目も後半はあんまり1周目と変わらんな、という気もするけれど、全体的には結構いいんじゃない？と思う絵になっている気がする。 <a href="./それっぽく描くコツ1周目.html">それっぽく描くコツ1周目</a>の最後に書いた感想から少し印象の変わった部分もあるので、そのアップデートも兼ねて、2周目が終わった時点での全体の感想をもう一度考えてみたい。</p><h3 id="_1周目の最後の時点で、自分が思っていたよりは上手くなっていたのかも" tabindex="-1"><a class="header-anchor" href="#_1周目の最後の時点で、自分が思っていたよりは上手くなっていたのかも"><span>1周目の最後の時点で、自分が思っていたよりは上手くなっていたのかも</span></a></h3><p>1周目の最後の時点ではちょっと上手くなったかも？くらいに思っていたが、 2周目を見ていると結構上手くなっているな、と思った。</p><p>自分の実力は、どうも自分が思っていたよりはあがっていたんじゃないか。 全体的にバランスを取る能力は向上している気がする。これはこのページの途中にも「2周目はバランスが大きく改善している」として書いているのでそちらも参照のこと。</p><h3 id="シルエットから描いたら割とそれっぽくなるようになっていた" tabindex="-1"><a class="header-anchor" href="#シルエットから描いたら割とそれっぽくなるようになっていた"><span>シルエットから描いたら割とそれっぽくなるようになっていた</span></a></h3><p>1周目の時点ではシルエットから描いても別にそれっぽくならんがな！と思っていたが、実は最後の方にはそれっぽくする技術が身についていたっぽい、と思っている。 だからこの主張は誇大広告だ！という一周目の印象は訂正したい。 シルエットから描くだけではそれっぽくならないが、 本書を最後までやると割とシルエットから描いてそれっぽく出来るようにはなっている気がした。</p><p>シルエットやアタリを描くあたりで全体的なバランスを考える事に注力する、というのをマスターするとそれっぽく描けるようになり、 それは本書を最後までやるとまぁまぁ出来るようになった。</p><p>序盤の解説では練習すると出来るようになる、という風な書き方では無かったので「そんなうまく行かない！」という気分になる部分があったが、 シルエットから描く書き方で「練習すれば」出来るようになる、という話と思えば、結構当たっているな、と思った。</p><h3 id="最終的なクオリティと掛ける時間をある程度コントロール出来るようになった" tabindex="-1"><a class="header-anchor" href="#最終的なクオリティと掛ける時間をある程度コントロール出来るようになった"><span>最終的なクオリティと掛ける時間をある程度コントロール出来るようになった</span></a></h3><p>最初の試行錯誤でどのくらい時間を掛けるかで、最終的なクオリティをある程度コントロール出来るようになった。 もちろんどれだけ時間を掛けてもたどり着けない領域は普通にあるので、 好きなだけ上手く描けるようになったという意味では無い。</p><p>ただ、最初のシルエットのあたりで、このくらい時間を掛けてこのくらいにしよう、と思ってやると、だいたいそのくらいのものが出来るようになった。 掛けた時間があんまり無駄になる感じが無くて、最後のクオリティにそのまま反映されている気がする。 逆に、たぶんこれ以上やっても無駄だな、というのも分かっている気がする（本当にやってみた訳ではないので実はもっと良くなる可能性もあるが）。 たまに掛けた時間の割には変なものも出来るが（猫背のアフター1とか）、だいたいは最初の段階で「こんなもんでいいか」と思った程度のものが出来ている気がする。</p><p>これは細部で時間を凄い使って全体的にいまいち、となってしまいがちな初心者模写あるあるを防げているという点で、 この本の描き方の優れた特徴だと思う。 全体的な所を最初に意識するのはメリットは多い。</p><h3 id="描くのは早くなった-タイパが良い" tabindex="-1"><a class="header-anchor" href="#描くのは早くなった-タイパが良い"><span>描くのは早くなった（タイパが良い）</span></a></h3><p>シルエットとアタリのあたりで「ディテールでどれだけ頑張ってもこれ以上は良くならない」というラインが最初に決まるので、 ディテールでそれ以上無駄に試行錯誤して時間を潰す事は無くなり、結果として描き終わるのは早くなったと思う。 適当な所で諦められる、というか。</p><p>シルエットとアタリのところではそれなりに試行錯誤で時間を無駄にしているが、 ここの試行錯誤は回数が多くてもそんなに時間は掛からないので、自分的には割と満足行く時間で満足行くものが描けていると思う。</p><p>アタリを単にディテールに必要な最低限の目印、とする事で、工程には相当無駄が無いな、という印象がある。 一発描きの次くらいに早い描き方なんじゃないか。</p><p>ディテールで一回全部描き直すのは自分的にはちょうどいい塩梅だ。</p><h3 id="このくらいの絵が描ければ自分は十分かなぁ" tabindex="-1"><a class="header-anchor" href="#このくらいの絵が描ければ自分は十分かなぁ"><span>このくらいの絵が描ければ自分は十分かなぁ</span></a></h3><p>ここに描いたくらいの絵が描ければ自分は十分かなぁ、と思った。 これは描きやすい作例を模写した結果なので、実力はもうちょい上げる必要はあるが。</p><p>ただ今の自分的な課題は実力よりも何を描いていくか、という方に移ってきた気がする。 もうちょっとライブとかしていきたいけど何描こうかな〜みたいな。</p><p>もっと上手い絵は世の中にたくさんあるが、そこまでは自分はいいかな、という気がする。 それよりはこのくらいの絵で何をやりたいのか考えていきたい。</p><h2 id="tinyurl" tabindex="-1"><a class="header-anchor" href="#tinyurl"><span>tinyurl</span></a></h2><p>このページのtinyurl。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">https://tinyurl.com/4v7szysb</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div>`,78)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};